import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/mask_mechanism.B0tySBAV.png",t="/ascendc.github.io/assets/two_config_comparison.CAbQe2x2.png",e="/ascendc.github.io/assets/counter_first_n_calc.CcAPrwIT.png",o="/ascendc.github.io/assets/counter_high_dim_continuous.D1miVfzF.png",i="/ascendc.github.io/assets/normal_high_dim_bitwise.a4QGjPaf.png",r="/ascendc.github.io/assets/normal_high_dim_continuous.C-Ja2vyO.png",d="/ascendc.github.io/assets/external_counter_first_n.BDOMeJhP.png",h="/ascendc.github.io/assets/external_counter_continuous.o63tA7Hj.png",m="/ascendc.github.io/assets/external_normal_bitwise.BQolSus1.png",k="/ascendc.github.io/assets/external_normal_continuous.KkvIfL2h.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"SIMD计算说明","link":"/api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/SIMD_compute"},{"text":"掩码","link":"/api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/mask"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/mask.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/mask.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":3,"title":"掩码配置方式","slug":"掩码配置方式","link":"#掩码配置方式"},{"level":2,"title":"接口内设置Mask","slug":"接口内设置Mask","link":"#接口内设置Mask"},{"level":3,"title":"Counter模式","slug":"Counter模式","link":"#Counter模式"},{"level":3,"title":"Normal模式","slug":"Normal模式","link":"#Normal模式"},{"level":2,"title":"接口外设置Mask","slug":"接口外设置Mask","link":"#接口外设置Mask"},{"level":3,"title":"Counter模式","slug":"Counter模式-1","link":"#Counter模式-1"},{"level":3,"title":"Normal模式","slug":"Normal模式-1","link":"#Normal模式-1"},{"level":2,"title":"通用说明","slug":"通用说明","link":"#通用说明"},{"level":3,"title":"接口通用参数说明","slug":"接口通用参数说明","link":"#接口通用参数说明"}],"lastUpdated":1787658708000}'),g={name:"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/mask.md"};function u(w,s,A,v,M,b){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>掩码</h1><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>Mask（掩码）是Ascend C中用于控制数据元素是否参与计算的标识位序列。每一位掩码对应数据中的一个元素的位置，通过有效位和无效位标记，实现对数据操作的精细化开关控制。</p><p>掩码由固定位宽的数值表示：</p><ul><li>有效位（通常为1）：对应元素正常参与计算。</li><li>无效位（通常为0）：对应元素被屏蔽，不执行操作。</li></ul><p>在<a href="continuous_compute.html">连续计算</a>接口（即Tensor前n个数计算接口）中，Mask为输入参数n，表示前n个连续元素参与计算。</p><p>在<a href="high_dim_split.html">高维切分</a>接口中，Mask用于控制每次迭代内参与计算的元素。可通过连续模式和逐bit模式两种方式设置：</p><ul><li>连续模式：表示每个迭代内前面连续的多少个元素参与计算。</li><li>逐bit模式：表示按位控制哪些元素参与计算。</li></ul><p>基于Tensor前n个数计算及高维切分接口的Mask应用机制如<a href="#%E5%9B%BE1-%E6%8E%A9%E7%A0%81%E6%9C%BA%E5%88%B6%E8%AF%B4%E6%98%8E">图1掩码机制说明</a>所示。</p><p><strong>图1</strong> 掩码机制说明<br><img src="'+c+'" alt><a id="图1-掩码机制说明"></a></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><div data-filter="A3,910b"><ul><li>针对如下型号，Mask为硬件原生支持能力。调用Tensor前n个数据计算接口时，接口内部会将Mask设置为Counter模式，并在计算完成后恢复为系统默认的Normal模式。 <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li></ul></div><div data-filter="950"><ul><li>在Ascend 950PR/Ascend 950DT上，Mask为保证兼容性采用软仿实现，其硬件底层提供的能力与Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品存在一定差异。推荐使用Tensor前n个数据计算接口，该接口通过VF调用<a href="../../reg_vector_compute/reg_vector_compute.html">Reg矢量计算API</a>实现兼容。Tensor前n个数据计算接口内部不会将Mask模式切换为Normal模式。若调用该接口前已通过<a href="../mask_operations/SetMaskCount.html">SetMaskCount</a>设置为Counter模式，接口调用后仍为Counter模式；后续计算需要使用Normal模式时，需手动调用<a href="../mask_operations/SetMaskNorm.html">SetMaskNorm</a>进行设置。</li></ul></div></div><h3 id="掩码配置方式">掩码配置方式<a class="header-anchor" href="#掩码配置方式">​</a></h3><p>掩码的设置方式由具体接口的调用方式和模板参数isSetMask共同决定，支持接口内设置Mask和接口外设置Mask两种模式。</p><p><strong>表1</strong> Mask配置方式</p><table><thead><tr><th align="left">配置方式</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%86%85%E8%AE%BE%E7%BD%AEMask">接口内设置Mask</a>（默认）</td><td align="left">•通过矢量计算API的入参直接传递mask值。<br>•矢量计算API的模板参数isSetMask（仅部分API支持）用于控制接口传参还是外部API配置，默认值为true，表示接口传参。Mask对应于高维切分计算API中的mask/mask[]参数或者tensor前n个数据计算API中的calCount参数。</td></tr><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%A4%96%E8%AE%BE%E7%BD%AEMask">接口外设置Mask</a></td><td align="left">•通过<a href="../mask_operations/SetVectorMask.html">SetVectorMask</a>接口设置Mask值，矢量计算API的模板参数isSetMask设置为false，接口入参中的mask参数（对应于高维切分计算API中的mask/mask[]参数或者tensor前n个数据计算API中的calCount参数）不生效。<br>•适用于mask参数相同、多次重复使用的场景，无需在矢量计算API内部反复设置，会有一定的性能优势。</td></tr></tbody></table><p>Mask支持以下工作模式：</p><p><strong>表2</strong> Mask工作模式<a id="mask-mode"></a></p><table><thead><tr><th align="left">工作模式</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left">Normal模式</td><td align="left">默认模式，支持单次迭代内的Mask能力，需要开发者配置迭代次数，额外进行尾块的计算。<br><strong>Normal模式下，Mask用来控制单次迭代内参与计算的元素个数。</strong><br>通过调用<a href="../mask_operations/SetMaskNorm.html">SetMaskNorm</a>设置Normal模式。</td></tr><tr><td align="left">Counter模式</td><td align="left">简化模式，直接传入计算数据量，自动推断迭代次数，不需要开发者去感知迭代次数、处理非对齐尾块的操作；但是不具备单次迭代内的Mask能力。<br><strong>Counter模式下，Mask表示整个矢量计算参与计算的元素个数。</strong><br>通过调用<a href="../mask_operations/SetMaskCount.html">SetMaskCount</a>设置Counter模式。</td></tr></tbody></table><p>Mask操作的使用方式如下：</p><p><strong>表3</strong> Mask操作的使用方式</p><table><thead><tr><th align="left">配置方式</th><th align="left">工作模式</th><th align="left">前n个数据计算API</th><th align="left">高维切分计算API</th></tr></thead><tbody><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%86%85%E8%AE%BE%E7%BD%AEmask">接口内设置Mask</a></td><td align="left"><a href="#mask-mode">Normal模式</a></td><td align="left">不涉及。</td><td align="left">isSetMask模板参数设置为true，通过接口入参传入mask，根据使用场景配置dataBlockStride、repeatStride、repeatTime参数。</td></tr><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%86%85%E8%AE%BE%E7%BD%AEmask">接口内设置Mask</a></td><td align="left"><a href="#mask-mode">Counter模式</a></td><td align="left">isSetMask模板参数设置为true，通过接口入参传入mask。</td><td align="left">isSetMask模板参数设置为true，通过接口入参传入mask。<br>根据使用场景配置dataBlockStride、repeatStride参数。repeatTime传入固定值即可，建议统一设置为1，该值不生效。</td></tr><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%A4%96%E8%AE%BE%E7%BD%AEmask">接口外设置Mask</a></td><td align="left"><a href="#mask-mode">Normal模式</a></td><td align="left">不涉及。</td><td align="left">调用<a href="../mask_operations/SetVectorMask.html">SetVectorMask</a>设置Mask，之后调用高维切分计算API。<br>• isSetMask模板参数设置为false，接口入参中的mask值设置为占位符<code>MASK_PLACEHOLDER</code>，用于占位，无实际含义。<br>•根据使用场景配置repeatTime、dataBlockStride、repeatStride参数。</td></tr><tr><td align="left"><a href="#%E6%8E%A5%E5%8F%A3%E5%A4%96%E8%AE%BE%E7%BD%AEmask">接口外设置Mask</a></td><td align="left"><a href="#mask-mode">Counter模式</a></td><td align="left">isSetMask模板参数设置为false，调用<a href="../mask_operations/SetVectorMask.html">SetVectorMask</a>设置Mask，之后调用前n个数据计算API；接口入参中的count建议设置成1。</td><td align="left">调用<a href="../mask_operations/SetVectorMask.html">SetVectorMask</a>设置Mask，之后调用高维切分计算API。<br>• isSetMask模板参数设置为false；接口入参中的mask值设置为<code>MASK_PLACEHOLDER</code>，用于占位，无实际含义。<br>•根据使用场景配置dataBlockStride、repeatStride参数。repeatTime传入固定值即可，建议统一设置为1，该值不生效。</td></tr></tbody></table><p>用户需根据接口使用场景和参数配置正确选择掩码配置方式，如<a href="#%E5%9B%BE2-%E4%B8%A4%E7%A7%8D%E9%85%8D%E7%BD%AE%E6%96%B9%E5%BC%8F%E4%BB%A3%E7%A0%81%E5%AF%B9%E6%AF%94">图2 两种配置方式代码对比</a>所示：</p><p><strong>图2</strong> 两种配置方式代码对比<br><img src="'+t+`" alt><a id="图2-两种配置方式代码对比"></a></p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意：</p><ul><li><p>仅部分API支持isSetMask，具体支持情况请参考对应API的函数原型；</p></li><li><p>接口外设置Mask<strong>性能实践参考：<a href="../../../../../guide/operator_practice/simd_operator_optimization/vector_compute/mask_reuse_optimization.html">基于全局掩码复用的计算性能优化</a></strong>。</p></li></ul></div><h2 id="接口内设置Mask">接口内设置Mask<a class="header-anchor" href="#接口内设置Mask">​</a></h2><h3 id="Counter模式">Counter模式<a class="header-anchor" href="#Counter模式">​</a></h3><ul><li><p><strong>前n个数据计算</strong></p><p>采用<a href="#mask-mode">Counter模式</a>进行前n个数据计算，通过接口参数count指定参与计算的元素个数，接口内部会自动完成计算所需的Mask处理。不同产品的Mask模式恢复行为存在差异，具体请参考<a href="#%E6%A6%82%E8%BF%B0">概述</a>中的说明。</p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint64_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
</code></pre></div><p>如图3所示，采用Counter模式进行前n个数据计算，通过count参数指定参与计算的元素数量为128，接口内部会自动完成Mask的设置。</p><p><strong>图3</strong> Counter模式进行前n个数据计算示例<br><img src="`+e+`" alt><a id="图3-counter模式进行前n个数据计算示例"></a></p></li><li><p><strong>高维切分：连续计算</strong></p><p>在Counter模式连续计算中，Mask寄存器中的值只有低64bit有效，被当做参与计算的元素数量。高维切分矢量计算接口的repeatTime参数会被忽略，由系统内部根据元素数量自动计算。</p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskCount</span><span class="p">();</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mi">130</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskNorm</span><span class="p">();</span>
</code></pre></div><p>如图4所示，采用Counter模式下的高维切分连续计算接口，mask数组中仅低64bit有效，表示参与计算的元素总数为130。该模式接口内部的repeatTimes参数无效，系统根据mask值自动计算迭代次数。repeatParams参数配置表示DataBlock间存在间隔，迭代间连续。</p><p><strong>图4</strong> Counter模式进行高维切分连续计算示例<br><img src="`+o+`" alt><a id="图4-counter模式进行高维切分连续计算示例"></a></p></li></ul><h3 id="Normal模式">Normal模式<a class="header-anchor" href="#Normal模式">​</a></h3><p>在<a href="#mask-mode">Normal计算模式</a>中，Mask寄存器会作为每个Repeat的掩码使用。只有高维切分支持此模式，在接口上区分为逐bit模式和连续模式。</p><p><strong>注：Normal为默认模式。若未发生模式切换，则无需重复配置该模式。</strong></p><ul><li><p><strong>高维切分：逐bit计算</strong></p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">int8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="w"> </span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mh">0x69A569A569A569A5</span><span class="p">,</span><span class="w"> </span><span class="mh">0x69A569A569A569A5</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
</code></pre></div><p>如图5所示，采用Normal模式进行逐bit计算时，mask参数以位数组形式控制每个元素是否参与计算，详细展示了第一个DataBlock中元素的计算过程。repeatParams参数配置表示DataBlock间存在间隔，迭代间连续。</p><p><strong>图5</strong> Normal模式高维切分逐bit计算示例<br><img src="`+i+`" alt><a id="图5-normal模式高维切分逐bit计算示例"></a></p></li><li><p><strong>高维切分：连续计算</strong></p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">int8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
</code></pre></div><p>如图6所示，采用Normal模式进行连续计算时，mask参数表示迭代内连续参与计算的元素数量为128。repeatParams参数配置表示DataBlock间存在间隔，迭代间连续。</p><p><strong>图6</strong> Normal模式进行高维切分连续计算示例<br><img src="`+r+`" alt><a id="图6-normal模式进行高维切分连续计算示例"></a></p></li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>在Normal模式的高维切分连续计算场景下，每次迭代内能够处理的元素个数与操作数的数据类型位宽有关：操作数为16位时，mask∈[0, 128]；操作数为32位时，mask∈[0, 64]；操作数为64位时，mask∈[0, 32]。</p><p>当mask大于当前数据类型在单次repeat内可处理的最大元素个数时，仍按一次repeat执行，即按该最大元素个数执行，不支持超过最大元素个数的mask控制。例如：16位操作数单次repeat最多处理128个元素，32位操作数最多处理64个元素，64位操作数最多处理32个元素。</p></div><h2 id="接口外设置Mask">接口外设置Mask<a class="header-anchor" href="#接口外设置Mask">​</a></h2><h3 id="Counter模式-1">Counter模式<a class="header-anchor" href="#Counter模式-1">​</a></h3><ul><li><p><strong>前n个数据计算</strong></p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskCount</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetVectorMask</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MaskMode</span><span class="o">::</span><span class="n">COUNTER</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">128</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskNorm</span><span class="p">();</span>
<span class="c1">// ResetMask无需在每次计算接口调用后调用，仅在需显式重置掩码状态时使用</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetMask</span><span class="p">();</span>
</code></pre></div><p><strong>图7</strong> 接口外设置Mask，Counter模式前n个数据计算示例<br><img src="`+d+`" alt><a id="图7-接口外设置Mask-counter模式前n个数据计算示例"></a></p></li><li><p><strong>高维切分：连续计算</strong></p><p>在<a href="#mask-mode">Counter计算模式</a>中，Mask寄存器中的值只有低64bit有效，被当做参与计算的元素数量。同时高维切分矢量计算接口的repeatTime参数会被忽略，由系统内部根据元素数量自动计算。</p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">int8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="w"> </span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskCount</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetVectorMask</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MaskMode</span><span class="o">::</span><span class="n">COUNTER</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">130</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MASK_PLACEHOLDER</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskNorm</span><span class="p">();</span>
<span class="c1">// ResetMask无需在每次计算接口调用后调用，仅在需显式重置掩码状态时使用</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetMask</span><span class="p">();</span>
</code></pre></div><p><strong>图8</strong> 接口外设置Mask，Counter模式连续计算示例<br><img src="`+h+`" alt><a id="图8-接口外设置Mask-counter模式连续计算示例"></a></p></li></ul><h3 id="Normal模式-1">Normal模式<a class="header-anchor" href="#Normal模式-1">​</a></h3><p>在<a href="#mask-mode">Normal计算模式</a>中，Mask寄存器会作为每个Repeat的掩码使用。只有高维切分支持此模式，在接口上区分为逐bit模式和连续模式。</p><p><strong>注：Normal为默认模式。若未发生模式切换，则无需重复配置该模式。</strong></p><ul><li><p><strong>高维切分：逐bit计算</strong></p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">int8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskNorm</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetVectorMask</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MaskMode</span><span class="o">::</span><span class="n">NORMAL</span><span class="o">&gt;</span><span class="p">(</span><span class="mh">0x69A569A569A569A5</span><span class="p">,</span><span class="w"> </span><span class="mh">0x69A569A569A569A5</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MASK_PLACEHOLDER</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
<span class="c1">// ResetMask无需在每次计算接口调用后调用，仅在需显式重置掩码状态时使用</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetMask</span><span class="p">();</span>
</code></pre></div><p><strong>图9</strong> 接口外设置Mask，Normal模式高维切分逐bit计算示例<br><img src="`+m+`" alt><a id="图9-接口外设置Mask-normal模式高维切分逐bit计算示例"></a></p></li><li><p><strong>高维切分：连续计算</strong></p><p>调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">half</span><span class="w"> </span><span class="n">addsValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">UnaryRepeatParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">{</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetMaskNorm</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetVectorMask</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MaskMode</span><span class="o">::</span><span class="n">NORMAL</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">128</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Adds</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">addsValue</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MASK_PLACEHOLDER</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
<span class="c1">// ResetMask无需在每次计算接口调用后调用，仅在需显式重置掩码状态时使用</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetMask</span><span class="p">();</span>
</code></pre></div><p><strong>图10</strong> 接口外设置Mask，Normal模式高维切分连续计算示例<br><img src="`+k+`" alt><a id="图10-接口外设置Mask-normal模式高维切分连续计算示例"></a></p></li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>在Normal模式的高维切分连续计算场景下，每次迭代内能够处理的元素个数与操作数的数据类型位宽有关：操作数为16位时，mask∈[0, 128]；操作数为32位时，mask∈[0, 64]；操作数为64位时，mask∈[0, 32]。</p><p>当mask大于当前数据类型在单次repeat内可处理的最大元素个数时，仍按一次repeat执行，即按该最大元素个数执行，不支持超过最大元素个数的mask控制。例如：16位操作数单次repeat最多处理128个元素，32位操作数最多处理64个元素，64位操作数最多处理32个元素。</p></div><h2 id="通用说明">通用说明<a class="header-anchor" href="#通用说明">​</a></h2><h3 id="接口通用参数说明">接口通用参数说明<a class="header-anchor" href="#接口通用参数说明">​</a></h3><p>接口需要进行掩码操作时，需要传入通用参数，这些参数用于控制计算元素范围、迭代行为及掩码配置。以API Adds为例，展开说明了<strong>掩码相关参数</strong>的含义、输入类型及使用注意事项。</p><ul><li><p>tensor前n个数据计算</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Adds</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="o">&amp;</span><span class="w"> </span><span class="n">scalarValue</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">&amp;</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Adds</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="o">&amp;</span><span class="w"> </span><span class="n">scalarValue</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[],</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">UnaryRepeatParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div></li><li><p>mask连续模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Adds</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="o">&amp;</span><span class="w"> </span><span class="n">scalarValue</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">UnaryRepeatParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div></li></ul></li></ul><p><strong>表4</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">isSetMask</td><td align="left">是否在接口内部设置Mask。<br>• true，表示在<a href="#%E6%8E%A5%E5%8F%A3%E5%86%85%E8%AE%BE%E7%BD%AEMask">接口内设置Mask</a>。<br>• false，表示在<a href="#%E6%8E%A5%E5%8F%A3%E5%A4%96%E8%AE%BE%E7%BD%AEMask">接口外设置Mask</a>，开发者需要使用<a href="../mask_operations/SetVectorMask.html">SetVectorMask</a>接口设置mask值。这种模式下，接口入参中的mask值设置为占位符<code>MASK_PLACEHOLDER</code>，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表5</strong> 掩码相关参数<a id="sheet2"></a></p><table><thead><tr><th align="left">参数名称</th><th align="left">输入/输出</th><th align="left">含义</th></tr></thead><tbody><tr><td align="left">count</td><td align="left">输入</td><td align="left">参与计算的元素个数。<br>在Counter模式下，当isSetMask = false，count会被转换成掩码表示。前count位设置为1，表示前count个元素参与计算，其余元素被屏蔽。</td></tr><tr><td align="left">mask[]/mask</td><td align="left">输入</td><td align="left">mask存储在一个128bit的寄存器中，在掩码Normal模式下从低位到高位按位控制参与计算的元素，该位的值为1表示参与计算，0表示不参与，最多可以控制128个元素是否参与计算，有效位数与参与计算的数据类型有关。<br>接口提供两种方式设置掩码Normal模式下的mask，控制每次迭代内参与计算的元素。<br>•逐bit模式：输入为uint64_t类型的数组mask[]，直接设置mask寄存器的值，输入的mask数组长度大于等于2，其中有效的位数与操作数的类型有关：<br>当操作数为16位时，一次迭代中有128个元素参与计算，需要使用两个uint64_t类型的数据进行设置，数组有效长度为2，maskLow∈[0, 2<sup>64</sup>-1]， maskHigh∈[0, 2<sup>64</sup>-1]；<br>当操作数为32位时，一次迭代有64个数参与计算，仅需一个uint64_t的数据即可，数组有效长度为1，maskLow∈[0, 2<sup>64</sup>-1]， maskHigh = 0；<br>当操作数为64位时，一次迭代有32个元素参与计算，数组长度为1，mask[0]的有效位数为32，maskLow∈[0, 2<sup>32</sup>-1]，maskHigh = 0。<br>例如，mask=[8, 2]，8和2分别表示低位的64bit和高位的64bit，8=0b1000，表示仅第4个元素参与计算；2=0b0010表示第66（64+2）个元素参与计算。<br>•连续模式：输入为uint64_t的值mask，表示mask寄存器从低位开始连续多少位被设置为1，表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。<br>当操作数为16位时，mask∈[0, 128]；<br>当操作数为32位时，mask∈[0, 64]；<br>当操作数为64位时，mask∈[0, 32]。<br>注：连续模式下，mask超出范围按照对应数据类型下mask最大值计算；mask = 0表示指令不会执行计算操作，该接口将被视为NOP（空操作）；若设成了负值可能产生未定义行为。</td></tr></tbody></table><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><ul><li><p>参数count的最大取值受限于输入数据总容量，该容量由系统Unified Buffer（UB）大小限制及操作数数据类型共同约束：不同数据类型下，相同UB容量内可容纳的最大元素数量不同。</p></li><li><p>参数mask[]/mask仅在高维切分计算时有效，mask为0时，目的操作数保持原值。</p></li></ul></div></article></div>`,1)])])}const C=a(g,[["render",u]]);export{f as __pageData,C as default};
